CREATE TABLE "public"."species" (
  "Id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Species"     text,
  "Prefinished" boolean                  DEFAULT false,
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "species_pkey" PRIMARY KEY ("Id")
);

ALTER TABLE "public"."species"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."species"
  ADD CONSTRAINT "species_Id_key" UNIQUE ("Id");

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.species
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."species"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for sales editors" ON "public"."species"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'designer'::text, 'scheduler'::text, 'reception'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."species"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for sales editors" ON "public"."species"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'designer'::text, 'scheduler'::text, 'reception'::text])));

REVOKE ALL ON SEQUENCE "public"."species_Id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."species_Id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."species_Id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."species_Id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."species_Id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."species_Id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."species_Id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."species_Id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."species" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."species" TO "service_role";

COMMENT ON TABLE "public"."species" IS 'All Species';

REVOKE ALL ON TABLE "public"."species" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."species" TO "postgres";
